let n = +readline();
let type = readline();
let lines = (250 - n) / 50;
let drawing = `#           #
#           #
 #         #
  #       #
   #     #`.split("\n").reverse();

if (n < 250) {
  for (let i = 0; i < lines; i++) {
    drawing[i] = drawing[i]?.replace(/#( +)#/, (_, spaces) => `#${'.'.repeat(spaces.length)}#`)
  }
  if (type != 'espresso') drawing[lines - 1] = drawing[lines - 1].replace(/\./g, '~')
}

console.log(drawing.reverse().join("\n"))
console.log("    #####")
